async function addProduct(e){e.preventDefault();const draft={...form,name:form.name.trim(),brand:form.brand.trim()||'Shopora'};if(!draft.name){toast('Enter a product name first');return}toast('Writing product title, 6 key features and description…');let copy={title:draft.name,bullets:[],description:draft.description.trim()};try{const response=await fetch('/api/product-copy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:draft.name,brand:draft.brand,category:draft.category,price:draft.price,mrp:draft.old,details:draft.description})});const result=await response.json();if(!response.ok)throw new Error(result.error||'AI copy request failed');copy={title:result.title||draft.name,bullets:Array.isArray(result.bullets)?result.bullets.slice(0,6):[],description:result.description||draft.description};}catch(error){toast(error.message||'AI copy unavailable; adding product with your supplied details');}const features=copy.bullets.length?'\\n\\nKey features\\n'+copy.bullets.map((x,i)=>(i+1)+'. '+x).join('\\n'):'';const p={...draft,id:'local'+Date.now(),name:copy.title||draft.name,marketingTitle:copy.title||draft.name,features:copy.bullets,price:+draft.price,old:+(draft.old||draft.price),stock:+(draft.stock||0),rating:4.5,reviews:0,tag:'NEW',color:'#e8eaf4',delivery:'2 days',specs:copy.bullets.join(' · ')||'See product details',description:(copy.description||'')+features,seller:'Shopora Retail',returnDays:7};setProducts(a=>[p,...a]);setForm({name:'',brand:'',category:'Electronics',price:'',old:'',stock:'',emoji:'📦',description:''});toast(copy.bullets.length?'Product added with AI-written copy':'Product added; AI copy was unavailable, so check its description');}
